#include <vector>

std::vector<long long> row_sums(const std::vector<std::vector<int>>& grid) {
    std::vector<long long> sums;
    sums.reserve(grid.size());
    for (const auto& row : grid) {
        long long total = 0;
        for (int x : row) total += x;
        sums.push_back(total);
    }
    return sums;
}
